def links(lesson=None):
 sources=SOURCES if lesson is None else [(label,SOURCES[index][1]) for index,label in LESSON_SOURCES[lesson]]
 return '<ul>'+''.join(f'<li><a href="{E(u)}">{E(t)}</a></li>' for t,u in sources)+'</ul>'
def table(rows):return '<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable worked example"><table><caption>Fictional worked example — not an approved site record</caption><thead><tr>'+''.join('<th scope="col">'+E(x)+'</th>' for x in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+E(x)+('</th>' if i==0 else '</td>') for i,x in enumerate(row))+'</tr>' for row in rows[1:])+'</tbody></table></div>'
