 body+='</section><section class="panel"><h2>Worked example</h2>'+table(l['worked'])+'</section>'
 body+=f'<section class="panel"><h2>Apply it · Activity {i}</h2><p>{E(l["activity"])}</p><a href="/academy-module-4-workbook.html#activity-{i}">Open workbook activity</a><details><summary>Compare with model reasoning</summary><p>{E(l["model"])}</p></details></section><section class="panel"><h2>Knowledge check</h2><form class="quiz" data-lesson="{i}">'+quiz(l['quiz'],1)+'<button type="submit" disabled>Check answer</button><p class="quiz-result" role="status"></p></form></section>'
 body+='<button type="button" id="mark-studied">Mark this lesson studied</button><p id="studied-status" role="status"></p><nav class="lesson-nav" aria-label="Lesson sequence">'+(f'<a href="/academy-lesson-4-{i-1}.html">← Previous lesson</a>' if i>1 else '<a href="/academy-module-4.html">← Overview</a>')+(f'<a href="/academy-lesson-4-{i+1}.html">Next lesson →</a>' if i<10 else '<a href="/academy-module-4-assessment.html">Final assessment →</a>')+'</nav><details><summary>Technical sources</summary>'+links(i)+'</details>'
 page(l['title'],body,f'academy-lesson-4-{i}.html',f'data-lesson="{i}"')
