runtime=sum(json.loads(p.read_text())['duration'] for p in A.glob('lesson-*-timing.json'))
body=f'<section class="hero"><div class="eyebrow">Module 04 · Review candidate</div><h1>Installation Qualification (IQ)</h1><p class="lede">Verify the installed system and prepare an evidence-linked handover to operational qualification.</p><p><span class="pill">10 narrated lessons</span><span class="pill">40 diagrams</span><span class="pill">10 worked examples</span><span class="pill">20 assessment questions</span></p><a class="button" href="/academy-lesson-4-1.html">Start Lesson 4.1 →</a></section><div class="grid"><section class="panel"><h2>Continue the V-201 case</h2><p>Inspect the fictional V-201 oral-liquid vessel against a controlled installation baseline. No aseptic process, site-specific acceptance criteria or actual qualification records are represented.</p><p>Prerequisite: <a href="/academy-module-3.html">Module 3 — Design Qualification</a>.</p></section><section class="panel"><h2>Learning time and format</h2><p>{runtime/60:.1f} minutes of narration. Allow approximately 4–5 hours including 200 minutes of suggested practice, reading and assessment. These are unmeasured planning estimates, not accredited contact time.</p><p>Core explanations and worked reasoning are narrated. Reference tables restate the examples; activities and model answers are reading exercises.</p></section></div><section class="panel"><h2>Your self-study progress</h2><p id="progress-text">0 of 10 lessons marked studied · 0 of 10 checks passed</p><progress id="progress-bar" max="10" value="0" aria-label="Lessons marked studied"></progress><p id="assessment-status">Final assessment not completed.</p><p>Saving is optional and defaults off. Progress is not a GMP training record.</p></section><h2>Lessons</h2><div class="grid">'
for l in D['lessons']:body+=f'<article class="panel"><div class="eyebrow">Lesson 4.{l["id"]}</div><h3>{E(l["title"])}</h3><p>{E(l["objective"])}</p><a href="/academy-lesson-4-{l["id"]}.html">Open lesson 4.{l["id"]} →</a></article>'
body+='</div><p><a href="/academy-module-4-workbook.html">Workbook and templates</a> · <a href="/academy-module-4-assessment.html">20-question assessment</a> · <a href="/academy-module-4-sources.html">Sources and privacy</a> · <a href="/academy-module-4-review.html">Review package</a></p>'
page(D['title'],body,'academy-module-4.html')
body='<h1>IQ practical workbook</h1><p class="lede">Develop an installation baseline, evidence row, discrepancy record and OQ handover recommendation.</p><p>Fictional V-201 oral-liquid vessel only. Do not enter confidential site or patient data. Answers are not stored or transmitted; print before closing.</p><button id="print-workbook" type="button">Print / save workbook as PDF</button><p><a href="/assets/academy/module-4/iq-template.csv" download>IQ evidence template (CSV)</a> · <a href="/assets/academy/module-4/findings-template.csv" download>Installation findings template (CSV)</a></p>'
for l in D['lessons']:
 i=l['id'];body+=f'<section class="panel" id="activity-{i}"><h2>Activity {i} · {E(l["title"])}</h2><p>Suggested time: 20 minutes. Revisit the narrated lesson and worked example before responding.</p><p>{E(l["activity"])}</p><label for="work-{i}">Your response</label><textarea id="work-{i}"></textarea><details><summary>Model reasoning</summary><p>{E(l["model"])}</p></details><a href="/academy-lesson-4-{i}.html">Revisit lesson</a></section>'
body+='<section class="panel"><h2>Capstone rubric</h2><p>Give each dimension 0 (missing), 1 (partial) or 2 (supported): controlled baseline; criteria and actual observations; evidence traceability; discrepancy impact and verification; bounded handover recommendation. This 10-point self-review rubric is not a competency certification. Invented evidence or unsupported routine-use approval requires correction irrespective of the score.</p></section>'
page('IQ practical workbook',body,'academy-module-4-workbook.html')
body='<h1>Apply the IQ reasoning</h1><p>20 distinct application questions. This open-book self-study assessment exposes its answer key in the source and below. The suggested practice target is 85% (17/20), not a regulatory threshold, IQ acceptance rule or proof of independent competence. Unanswered questions must be completed before scoring. Answers are not sent to a server.</p><form class="quiz" data-final="true">'+''.join(quiz(q,i) for i,q in enumerate(QUESTIONS,1))+'<button type="submit" disabled>Score assessment</button><p class="quiz-result" role="status" tabindex="-1"></p></form><details><summary>Answer key and explanations</summary>'+''.join(f'<p>{i}. {E(q["options"][q["answer"]])} — {E(q["feedback"])}</p>' for i,q in enumerate(QUESTIONS,1))+'</details><noscript><p>Interactive scoring requires JavaScript; use the answer key for self-review.</p></noscript>'
